const itemStackPower=level=>itemCopiesAtTier(level)*itemTierMultiplier(level);
function itemModifierSummary(mods={},strength=1){const parts=[];for(const [key,value] of Object.entries(mods)){if(key==='range')parts.push(`${value>=1?'+':''}${Math.round((value**strength-1)*100)}% RANGE`);else if(key==='speed')parts.push(`${value>=1?'+':''}${Math.round((value**strength-1)*100)}% MOVE SPEED`);else if(key==='attack')parts.push(`${value>=0?'+':''}${Math.round(value*strength*100)}% ATTACK SPEED`);else parts.push(`${value>=0?'+':''}${simpleNumber(value*strength)} ${humanStat(key)}`);}return parts.join(' · ')||'ABILITY';}
function effectPowerText(effect,p,strength=1){switch(effect){case'heal':return`+${simpleNumber((2+p)*strength)} HP`;case'materials':return`+${Math.max(1,Math.floor((1+p)*strength))} WATER`;case'nova':return`${simpleNumber((8+p*4)*strength)} AREA DAMAGE`;case'slow':return`${simpleNumber((1+p*.25)*(1+Math.log2(strength)*.55))}s FREEZE`;case'burn':return`${simpleNumber((2+p)*strength)} BURN DAMAGE`;case'poison':return`${simpleNumber((3+p)*strength)} POISON DAMAGE`;case'shield':return`+${simpleNumber((2+p*2)*strength*SHIELD_GAIN)} SHIELD`;case'damageBuff':return`+${simpleNumber((8+p*3)*strength)}% DAMAGE · 5s`;case'attackBuff':return`+${simpleNumber((7+p*3)*strength)}% ATTACK SPEED · 5s`;case'speedBuff':return`+${simpleNumber((10+p*4)*strength)}% MOVE SPEED · 5s`;case'rangeBuff':return`+${simpleNumber((12+p*4)*strength)}% RANGE · 6s`;case'magnetBurst':return`PULL WATER · ${wholeMeters((180+p*35)*(1+Math.log2(strength)*.45))}`;case'homingShot':return`${simpleNumber((10+p*4)*strength)} HOMING DAMAGE`;case'orbitingBlade':return`${simpleNumber((7+p*3)*strength)} ORBIT DAMAGE`;case'knockback':return`KNOCKBACK · ${wholeMeters((20+p*8)*Math.sqrt(strength))}`;case'chain':return`${Math.max(1,Math.floor(2+p+Math.log2(strength)))} TARGETS · ${simpleNumber((5+p*2)*strength)} DAMAGE`;case'regen':return`+${simpleNumber((1+p)*strength)} HP · COOL GUNS`;case'crit':return`+${Math.max(1,Math.floor((1+p)*strength))} CRITICAL HITS`;case'cloneDrop':return`+${Math.min(48,Math.max(1,Math.floor((1+p)*strength)))} WATER DROPS`;case'cooldown':return`-${simpleNumber((1-(1-(20+p*8)/100)**strength)*100)}% COOLDOWNS`;default:return'ABILITY';}}
function activePowerText(active,p,strength=1){switch(active){case'orbitDamage':return`${simpleNumber((5+p*2)*strength)} ORBIT DAMAGE`;case'orbitHeal':return`+${simpleNumber((1+Math.ceil(p/2))*strength)} HP / PULSE`;case'radialPhysical':return`${Math.floor(4+p+Math.log2(strength))} BURST SHOTS`;case'radialElement':return`${Math.floor(5+p+Math.log2(strength))} ELEMENT SHOTS`;case'damagePulse':return`${simpleNumber((8+p*4)*strength)} AREA DAMAGE`;case'healPulse':return`+${simpleNumber((2+p)*strength)} HP / PULSE`;case'guardianShot':return`${simpleNumber((7+p*3)*strength)} GUARDIAN DAMAGE`;case'boomerangBurst':return`${1+Math.ceil(p/2)+Math.floor(Math.log2(strength))} RETURNING SHOTS`;case'chainNova':return`${Math.max(1,Math.floor(2+p+Math.log2(strength)))} TARGETS · ${simpleNumber((6+p*3)*strength)} DAMAGE`;case'shieldWave':return`+${simpleNumber((1+p)*strength*SHIELD_GAIN)} SHIELD · PUSH`;default:return'ACTIVE ABILITY';}}
function itemPowerText(def={},tier=1){const strength=itemStackPower(tier);if(Object.keys(def.mods||{}).length)return itemModifierSummary(def.mods,strength);const power=(def.power||0)*itemPowerMultiplier;return def.active?activePowerText(def.active,power,strength):effectPowerText(def.effect,power,strength);}
function itemDrawbackText(def={},tier=1){const drawback=def.drawback||{},copies=itemCopiesAtTier(tier);if(tier<=1)return compactBadText(drawback.text);if(Number.isFinite(drawback.amount)){const amount=drawback.amount*copies;if(['damage','attack'].includes(drawback.stat))return`${amount<0?'−':'+'}${Math.abs(Math.round(amount*100))}% ${humanStat(drawback.stat)}`;return`${amount<0?'−':'+'}${Math.abs(simpleNumber(amount))} ${humanStat(drawback.stat)}`;}if(Number.isFinite(drawback.multiplier)){const percent=Math.abs(Math.round((drawback.multiplier**copies-1)*100));return`${drawback.multiplier<1?'−':'+'}${percent}% ${humanStat(drawback.stat)}`;}return compactBadText(drawback.text);}
function itemTriggerText(def={}){return def.active?'ALWAYS ACTIVE':SIMPLE_TRIGGER_LABELS[def.trigger]||'PASSIVE';}
function weaponFeatureText(def={}){const parts=[];if(def.pellets)parts.push(`${def.pellets} SHOTS`);if(def.burst)parts.push(`${def.burst} BURST`);if(def.pierce)parts.push(`${def.pierce} PIERCE`);if(def.ricochet)parts.push(`${def.ricochet} BOUNCE`);if(def.split)parts.push(`${def.split} SPLIT`);if(def.chain)parts.push(`${def.chain} CHAIN`);if(def.blast)parts.push(`${wholeMeters(def.blast)} BLAST`);if(def.burn)parts.push(`${def.burn} BURN`);if(def.slow)parts.push('SLOW');if(def.homing)parts.push('HOMING');if(def.lifesteal)parts.push('HEAL ON HIT');if(def.knockback)parts.push('KNOCKBACK');if(def.pull)parts.push('PULL');if(def.returning)parts.push('RETURNS');if(def.mine)parts.push('MINE');if(def.melee)parts.push('MELEE THRUST');return parts.slice(0,2).join(' · ')||'AUTO AIM';}
function weaponAttacksPerMinute(def){return Math.max(1,Math.round(60/weaponAttackTime(def)));}
function weaponStatText(def,tier=1){return`+${Math.round(weaponDamageAtTier(def,tier))} DAMAGE · ${weaponAttacksPerMinute(def)} ATTACKS/MIN<br>+${wholeMeters(weaponLockRange(def))} RANGE`;}
function characterPowerText(c={}){if(!c.abilitySpec)return compactText(c.good||c.ability);const power=(c.abilitySpec.power||0)*itemPowerMultiplier;return`${SIMPLE_TRIGGER_LABELS[c.abilitySpec.trigger]||'POWER'} · ${effectPowerText(c.abilitySpec.effect,power)}`;}
function characterGoodText(c={}){let text=compactText(c.signature?c.signature.split('.')[0].replace(/^[^:]+:\s*/,''):c.good||c.ability);text=text.replace(/^(\d+) EXTRA AVOCADO TREES SPAWN EVERY ROUND$/,'+$1 TREES').replace(/^(\d+) EXTRA TREES · (\d+) FARMS SPAWN EVERY ROUND$/,'+$1 TREES · +$2 FARMS');return c.abilitySpec?`+100% ABILITY POWER · ${text}`:text;}
function characterDamageText(c={}){const percent=Math.round(((c.damage??1)-1)*100);return`${percent>=0?'+':'−'}${Math.abs(percent)}% DAMAGE`;}
function characterBaseStats(c={}){const hp=c.hp??10;return{hp,maxHp:hp,speed:c.speed??220,damage:c.damage??1,armor:c.armor??0,attack:c.attack??1,magnet:c.magnet??90,range:c.range??1,regen:c.regen??0,engineering:c.engineering??0,harvesting:c.harvesting??0,harvestingMultiplier:c.harvestingMultiplier??1,luck:c.luck??0,farmCapacity:c.farmCapacity??0,treeBonus:c.treeBonus??0};}
function effectiveHarvesting(actor=player){return Math.max(0,Math.floor((actor?.harvesting||0)*(actor?.harvestingMultiplier||1)));}
function characterRule(actor=player){return classes[actor?.classId||chosen]?.ruleSpec||null;}
function characterRuleText(c={}){return compactText(c.ruleSpec?.text||'No special rule');}
function characterRuleEnemyCount(actor,radius){return enemies.filter(enemy=>enemy.hp>0&&distance(actor,enemy)<=radius).length;}
function characterRuleModifiers(actor=player,actorWeapons=actor===player?weapons:actor?.weapon?[actor.weapon]:[]){
 const rule=characterRule(actor),mods={damage:1,attack:1,speed:1,range:1,armor:0};if(!actor||!rule)return mods;
 const closeCount=()=>characterRuleEnemyCount(actor,rule.radius||180),still=(actor.standingTime||0)>=1,weaponCount=Math.max(0,actorWeapons?.length||0),slots=classes[actor.classId||chosen]?.weaponSlots||6;
 if(rule.kind==='stillHarvestDamage'&&still)mods.damage+=Math.min(rule.cap,(actor.harvesting||0)*rule.amount);
 else if(rule.kind==='stillEngineeringAttack'&&still)mods.attack+=Math.min(rule.cap,(actor.engineering||0)*rule.amount);
 else if(rule.kind==='movingLuckSpeed'&&actor.moving)mods.speed+=Math.min(rule.cap,(actor.luck||0)*rule.amount);
 else if(rule.kind==='crowdDamage')mods.damage+=Math.min(rule.cap,closeCount()*rule.amount);
 else if(rule.kind==='isolatedRange'&&!characterRuleEnemyCount(actor,rule.radius))mods.range+=rule.amount;
 else if(rule.kind==='missingHealthAttack')mods.attack+=clamp(1-(actor.hp||0)/Math.max(1,actor.maxHp||1),0,1)*rule.amount;
 else if(rule.kind==='fullHealthDamage'&&(actor.hp||0)>=(actor.maxHp||1)-.01)mods.damage+=rule.amount;
 else if(rule.kind==='waterDamage')mods.damage+=Math.min(rule.cap,Math.floor(money/10)*rule.amount);
 else if(rule.kind==='poorSpeed'&&money<=rule.limit)mods.speed+=rule.amount;
 else if(rule.kind==='edgeAttack'&&Math.min(actor.x,actor.y,activeWorldWidth()-actor.x,activeWorldHeight()-actor.y)<=rule.distance)mods.attack+=rule.amount;
 else if(rule.kind==='centerArmor'&&Math.hypot(actor.x-activeWorldWidth()/2,actor.y-activeWorldHeight()/2)<=rule.radius)mods.armor+=rule.amount;
 else if(rule.kind==='farmAttack')mods.attack+=Math.min(rule.cap,farms.length*rule.amount);
 else if(rule.kind==='crowdArmor')mods.armor+=Math.min(rule.cap,closeCount()*rule.amount);
 else if(rule.kind==='lastSecondsDamage'&&remaining<=rule.seconds)mods.damage+=rule.amount;
 else if(rule.kind==='firstSecondsSpeed'&&elapsed<=rule.seconds)mods.speed+=rule.amount;
 else if(rule.kind==='weaponDamage')mods.damage+=Math.min(rule.cap,weaponCount*rule.amount);
 else if(rule.kind==='emptySlotAttack')mods.attack+=Math.min(rule.cap,Math.max(0,slots-weaponCount)*rule.amount);
 return mods;
}
function updateCharacterRule(actor,dt){
 const rule=characterRule(actor);if(!actor||!rule)return;
 if(rule.kind==='treeRegen'&&trees.some(tree=>tree.alive&&distance(actor,tree)<=rule.radius))actor.hp=Math.min(actor.maxHp,actor.hp+rule.amount*dt);
 if(rule.kind==='stillShield'){if((actor.standingTime||0)>=1){actor.ruleClock=(actor.ruleClock??rule.interval)-dt;if(actor.ruleClock<=0){actor.ruleClock=rule.interval;gainShield(actor,rule.amount/SHIELD_GAIN);showEffect('shield',actor.x,actor.y,78,.45);}}else actor.ruleClock=rule.interval;}
}
function characterBonusText(c={}){const stats=characterBaseStats(c),parts=[],signed=value=>value<0?`−${Math.abs(value)}`:`+${value}`;if(stats.armor)parts.push(`${signed(stats.armor)} ARMOR`);if(stats.attack!==1)parts.push(`${signed(Math.round((stats.attack-1)*100))}% ATTACK SPEED`);if(stats.range!==1)parts.push(`${signed(Math.round((stats.range-1)*100))}% RANGE`);if(stats.magnet!==90)parts.push(`${signed(Math.round((stats.magnet/90-1)*100))}% PICKUP RANGE`);if(stats.engineering)parts.push(`+${stats.engineering} ENGINEERING`);if(stats.harvesting)parts.push(`+${stats.harvesting} HARVESTING`);if(stats.harvestingMultiplier!==1)parts.push(`${signed(Math.round((stats.harvestingMultiplier-1)*100))}% HARVESTING`);if(stats.luck)parts.push(`+${stats.luck} LUCK`);if(stats.farmCapacity)parts.push(`+${stats.farmCapacity} FARM`);if(stats.treeBonus)parts.push(`+${stats.treeBonus} TREES`);return parts.join(' · ')||'BALANCED';}
function activeRangeMultiplier(actor=player,actorWeapons=actor===player?weapons:actor?.weapon?[actor.weapon]:[]){return actor?(actor.range||1)*(actor.rangeBoostTimer>0?1+(actor.rangeBoost||0):1)*characterRuleModifiers(actor,actorWeapons).range:1;}
function synergyNames(tags=[]){return tags.map(tag=>synergyTraits[tag]?.label||tag).join(' + ');}
function refreshSynergySources(force=false){const key=`${chosen}|${items.join('|')}`;if(!force&&key===synergyCacheKey)return synergySourceCounts;const counts={};for(const tag of classes[chosen]?.synergies||[])counts[tag]=(counts[tag]||0)+1;const itemCounts=new Map();for(const type of items)itemCounts.set(type,(itemCounts.get(type)||0)+1);for(const [type,copies] of itemCounts){const weight=Math.min(3,1+Math.floor(Math.log2(copies)));for(const tag of itemTypes[type]?.synergies||[])counts[tag]=(counts[tag]||0)+weight;}synergyCacheKey=key;synergySourceCounts=counts;return counts;}
function weaponSynergyStats(type){const def=weaponTypes[type],sources=refreshSynergySources(),stats={damage:1,rate:1,range:1,speed:1,status:1,blast:0,chain:0,ricochet:0,pierce:0,lifesteal:0,harvest:0,links:0,matches:[]};for(const tag of def?.synergies||[]){const links=Math.min(6,sources[tag]||0),trait=synergyTraits[tag];if(!links||!trait)continue;stats.links+=links;stats.matches.push(`${trait.label} ×${links}`);stats.damage+=links*(trait.damage||0);stats.rate+=links*(trait.rate||0);stats.range+=links*(trait.range||0);stats.speed+=links*(trait.speed||0);stats.status+=links*(trait.status||0);stats.blast+=links*(trait.blast||0);stats.lifesteal+=links*(trait.lifesteal||0);if(trait.chainStep)stats.chain+=Math.floor(links/trait.chainStep);if(trait.ricochetStep)stats.ricochet+=Math.floor(links/trait.ricochetStep);if(trait.pierceStep)stats.pierce+=Math.floor(links/trait.pierceStep);if(trait.harvest)stats.harvest+=links;}return stats;}
function synergyBonusText(stats){const parts=[];if(stats.damage>1)parts.push(`+${Math.round((stats.damage-1)*100)}% DMG`);if(stats.rate>1)parts.push(`+${Math.round((stats.rate-1)*100)}% SPEED`);if(stats.range>1)parts.push(`+${Math.round((stats.range-1)*100)}% RANGE`);if(stats.chain)parts.push(`+${stats.chain} CHAIN`);if(stats.ricochet)parts.push(`+${stats.ricochet} BOUNCE`);if(stats.pierce)parts.push(`+${stats.pierce} PIERCE`);if(stats.harvest)parts.push('BETTER DROPS');return parts.join(' · ')||'NEEDS A MATCH';}
function itemWeaponMatches(type){const tags=itemTypes[type]?.synergies||[];return weapons.filter(weapon=>weaponTypes[weapon.type]?.synergies?.some(tag=>tags.includes(tag))).length;}
function totalSynergyLinks(){return weapons.reduce((total,weapon)=>total+weaponSynergyStats(weapon.type).links,0);}
function weaponInspector(type,tier=1){const def=weaponTypes[type];if(!def)return null;const power=weaponPower(tier),synergy=weaponSynergyStats(type);return{title:`${def.name} ${roman(tier)}`,subtitle:'Simple weapon stats.',rows:[['Damage',`+${Math.round(weaponDamageAtTier(def,tier,synergy.damage))}`],['Attacks / min',Math.max(1,Math.round(60*synergy.rate/weaponAttackTime(def)))],['Range',`+${wholeMeters(weaponLockRange(def)*activeRangeMultiplier()*synergy.range)}`],['Good',weaponFeatureText(def),'good'],['Bad',compactBadText(def.drawback.text),'bad'],['Tier / power',`${roman(tier)} · ${power}`],['Synergies',synergyNames(def.synergies)],['Active links',synergy.matches.join(' · ')||'NONE'],['Linked bonus',synergyBonusText(synergy)]]};}
function itemInspector(type,tier=1){const def=itemTypes[type];if(!def)return null;const copies=itemCopiesAtTier(tier),power=itemStackPower(tier);return{title:`${def.name} ${roman(tier)}`,subtitle:'Simple item stats.',rows:[['Good',itemPowerText(def,tier),'good'],['Bad',itemDrawbackText(def,tier),'bad'],['Works',itemTriggerText(def)],['Synergies',synergyNames(def.synergies)],['Weapon matches',`${itemWeaponMatches(type)} EQUIPPED`],['Combined copies',`${copies} · POWER ×${power}`]]};}
function classInspector(classId){const c=classes[classId],weapon=weaponTypes[c?.weapon];if(!c)return null;return{title:c.name,subtitle:`${c.powerName||'POWER'} · ${weapon.name}`,rows:[['Good',characterGoodText(c),'good'],['Original rule',characterRuleText(c),'good'],['Ability',characterPowerText(c)],['Bad',compactBadText(c.bad||'No drawback'),'bad'],['Health / speed',`${c.hp} HP · ${meters(c.speed,true)}`],['Gun slots / weapon',`${c.weaponSlots} · ${weapon.name}`]]};}
function focusedInspector(element){if(!element)return null;if(element.dataset.shopWeapon!==undefined){const weapon=weapons[Number(element.dataset.shopWeapon)];return weapon&&weaponInspector(weapon.type,weapon.level);}if(element.dataset.shopItem){return itemInspector(element.dataset.shopItem,Number(element.dataset.shopItemLevel)||1);}if(element.dataset.shopClass){return classInspector(element.dataset.shopClass);}if(element.dataset.buy!==undefined||element.dataset.lock!==undefined){const offer=offers[Number(element.dataset.buy??element.dataset.lock)];return offer?.kind==='weapon'?weaponInspector(offer.type,1):itemInspector(offer?.type);}if(element.dataset.sell!==undefined||element.dataset.recycle!==undefined){const weapon=weapons[Number(element.dataset.sell??element.dataset.recycle)];return weapon&&weaponInspector(weapon.type,weapon.level);}if(element.dataset.upgrade!==undefined){const upgrade=currentUpgradeOptions[Number(element.dataset.upgrade)];return upgrade?{title:upgrade.name,subtitle:upgrade.desc,rows:[['Type','PERMANENT'],['Applies','THIS RUN']]}:null;}if(element.dataset.class){return classInspector(element.dataset.class);}if(element.dataset.difficulty!==undefined){const d=difficulties[Number(element.dataset.difficulty)];return d?{title:d.name,subtitle:d.desc,rows:[['Enemy HP',`${Math.round(d.hp*ENEMY_HEALTH*100)}%`],['Enemy speed',`${Math.round(d.speed*ENEMY_SPEED*100)}%`],['Enemy damage',`${Math.round(d.damage*ENEMY_DAMAGE*100)}%`],['Rewards',`${Math.round(d.reward*100)}%`]]}:null;}return null;}
function showFocusedStats(element){const panel=$('focusDetails');if(!panel)return;const detail=focusedInspector(element?.closest?.('button')||element);if(!detail&&panel.dataset.hasDetail)return;if(!detail){panel.classList.add('hidden');panel.innerHTML='<div class="inspect-placeholder">HIGHLIGHT A CARD TO SEE ITS STATS</div>';return;}panel.dataset.hasDetail='true';panel.classList.remove('hidden');panel.innerHTML=inspectMarkup(detail);}
function renderStatTabs(){const panel=$('statTabs');if(!panel)return;if(!panel.childElementCount){panel.innerHTML=statPageMeta.map(page=>`<button type="button" role="tab" data-stat-page="${page.id}" aria-controls="stats" aria-label="Show ${page.label} stats"><img src="${page.art}" alt=""><span>${page.label}</span></button>`).join('');panel.onclick=event=>{const button=event.target.closest('[data-stat-page]');if(!button)return;statsPage=button.dataset.statPage;updateUI();};}for(const button of panel.children){const active=button.dataset.statPage===statsPage;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;button.disabled=!player;}}
function syncItemTierState(){itemTierState.length=Math.min(itemTierState.length,items.length);for(let i=0;i<items.length;i++)if(!itemTierState[i]||itemTierState[i].type!==items[i])itemTierState[i]={type:items[i],level:1};return itemTierState;}
function itemStacks(){syncItemTierState();return itemTierState.map((entry,sourceIndex)=>entry?.level>0?{type:entry.type,level:entry.level,copies:2**(entry.level-1),sourceIndex}:null).filter(Boolean);}
function inspectInventoryItem(element){const card=element?.closest?.('[data-inventory-index]'),panel=$('itemInspect');if(!card||!panel)return;inventoryFocusIndex=Number(card.dataset.inventoryIndex)||0;const item=itemStacks()[inventoryFocusIndex],detail=item&&itemInspector(item.type,item.level);panel.innerHTML=inspectMarkup(detail);panel.classList.remove('hidden');}
function renderItemInventory(force=false){const container=$('itemSlots');if(!container)return;const key=`${chosen}|${items.join('|')}|${itemTierState.map(entry=>entry?.level||0).join('|')}|${weapons.map(weapon=>weapon.type).join('|')}`,stacks=itemStacks();if(!force&&key===inventoryRenderKey)return;inventoryRenderKey=key;container.innerHTML=stacks.length?stacks.map((item,index)=>{const linked=itemWeaponMatches(item.type)>0,label=`${itemTypes[item.type].name} level ${item.level}${linked?', linked synergy':''}`;return`<button class="item ${linked?'synergy-match':''}" data-inventory-index="${index}" title="${itemTypes[item.type].name} ${roman(item.level)}: ${itemTypes[item.type].desc} Synergy: ${synergyNames(itemTypes[item.type].synergies)}${linked?' · LINKED NOW':''}" aria-label="${label}"><img src="${artPaths[`item-${item.type}`]}" alt=""><b>${roman(item.level)}</b></button>`;}).join(''):'<span class="muted">Find items in the shop.</span>';container.onfocusin=event=>inspectInventoryItem(event.target);container.onpointerover=event=>inspectInventoryItem(event.target);if(!stacks.length)$('itemInspect')?.classList.add('hidden');}
function setInventoryFocus(element){const cards=[...document.querySelectorAll('#itemSlots [data-inventory-index]')],card=typeof element==='number'?cards[clamp(element,0,cards.length-1)]:element;if(!card)return;document.querySelector('.controller-focus')?.classList.remove('controller-focus');card.focus({preventScroll:true});card.classList.add('controller-focus');card.scrollIntoView({block:'nearest',inline:'nearest'});inspectInventoryItem(card);}
function moveInventoryFocus(dx,dy){const cards=[...document.querySelectorAll('#itemSlots [data-inventory-index]')];if(!cards.length)return;const current=cards.includes(document.activeElement)?document.activeElement:cards[clamp(inventoryFocusIndex,0,cards.length-1)];if(!current){setInventoryFocus(cards[0]);return placeGamepadCursor(cards[0]);}const from=current.getBoundingClientRect(),fx=from.left+from.width/2,fy=from.top+from.height/2;const choices=cards.filter(card=>card!==current).map(card=>{const r=card.getBoundingClientRect(),x=r.left+r.width/2-fx,y=r.top+r.height/2-fy,forward=x*dx+y*dy;return{card,forward,score:forward+Math.abs(x*dy-y*dx)*2};}).filter(choice=>choice.forward>4).sort((a,b)=>a.score-b.score),next=choices[0]?.card||current;setInventoryFocus(next);placeGamepadCursor(next);}
function setScreen(name=state){document.body.dataset.screen=name;if(name==='playing'){gamepadCursorScreen='';$('gamepadCursor')?.classList.remove('visible');clearGamepadCursorTarget();}}
function toggleInventoryMode(open=state!=='inventory'){if(open){if(state!=='playing')return false;if(!items.length){floatText(player.x,player.y-75,'NO ITEMS YET','#d1f56b',17);rumble(55,.05,.12);return false;}saveRun();state='inventory';setScreen();player.moving=false;$('inventoryPanel').hidden=false;renderItemInventory(true);$('pause').textContent='CLOSE ITEMS';$('worldInspect')?.classList.add('hidden');queueMicrotask(()=>setInventoryFocus(inventoryFocusIndex));rumble(70,.08,.18);return true;}if(state!=='inventory')return false;state='playing';setScreen();$('inventoryPanel').hidden=true;document.querySelector('.controller-focus')?.classList.remove('controller-focus');document.activeElement?.blur?.();$('itemInspect')?.classList.add('hidden');$('pause').textContent=onlineRole==='guest'?'HOST CONTROLS':'PAUSE';rumble(55,.06,.12);return true;}
function setControllerFocus(el){if(!el)return;document.querySelector('.controller-focus')?.classList.remove('controller-focus');el.focus({preventScroll:true});el.classList.add('controller-focus');el.scrollIntoView({block:'nearest',inline:'nearest'});showFocusedStats(el);}
function controllerTargets(){return [...document.querySelectorAll('#overlay button:not(:disabled):not(.offer-lock)')];}
