function chooseSpawnPoint(padding=30){let x,y;for(let attempt=0;attempt<12;attempt++){const angle=rand(0,TAU),radius=rand(Math.max(W,H)*.62,Math.max(W,H)*.9);x=clamp(player.x+Math.cos(angle)*radius,padding,activeWorldWidth()-padding);y=clamp(player.y+Math.sin(angle)*radius,padding,activeWorldHeight()-padding);if(Math.hypot(x-player.x,y-player.y)>Math.min(W,H)*.55)break;}return{x,y};}
