 const linkedWeapons=weapons.filter(weapon=>weaponSynergyStats(weapon.type).links>0).length,linkedItems=itemStacks().filter(item=>itemWeaponMatches(item.type)>0).length,specialties=synergyNames(classes[chosen].synergies);
 const statPages={
  combat:[['Damage',timed(`${Math.round(damage*100)}%`,damageActive,player.damageBoostTimer),damageActive],['Attack speed',timed(`${Math.round(attack*100)}%`,attackActive,player.attackBoostTimer),attackActive],['Weapon range',timed(lockRangeText,rangeActive,player.rangeBoostTimer),rangeActive],['Critical charges',Math.floor(player.nextCrit||0)],['Weapons',`${weapons.length} / ${weaponSlotLimit()}`],['Synergy links',totalSynergyLinks()]],
  defense:[['Health',`${Math.ceil(player.hp)} / ${player.maxHp}`],['Maximum HP',player.maxHp],['Armor',armor],['Damage resist',`${resist}%`],['Shield',Math.ceil(player.shield||0)],['Regeneration',`${Number(player.regen||0).toFixed(1)} HP/s`]],
  grove:[['Move speed',timed(meters(speed,true),speedActive,player.speedBoostTimer),speedActive],['Pickup range',meters(player.magnet)],['Dash',dashTimer>0?`${dashTimer.toFixed(1)}s`:'READY'],['Engineering',Math.floor(player.engineering||0)],['Harvesting',Math.floor(player.harvesting||0)],['Luck',Math.floor(player.luck||0)],['Repeat item chance',`${Math.round(shopRepeatChance()*100)}%`],['Trees / round',Math.min(treeSpawns.length,3+crewTreeBonus())],['Farms',`${farms.length} / ${Math.floor(player.farmCapacity||0)}`]],
  run:[['Level',level],['Experience',`${xp} / ${xpGoal}`],['Round',`${wave} / ${MAX_WAVES}`],['Water',money],['Kills',kills],['Items',`${items.length} / ∞`]],
  synergy:[['Original rule',characterRuleText(classes[chosen]),ruleActive],['Synergy links',totalSynergyLinks()],['Active traits',activeTraits],['Character specialties',specialties],['Linked weapons',`${linkedWeapons} / ${weapons.length}`],['Linked items',linkedItems],['Trait sources',Object.values(refreshSynergySources()).reduce((sum,value)=>sum+value,0)]]
 };
 renderStatTabs();
 const stats=statPages[statsPage]||statPages.combat;
 $('stats').innerHTML=stats.map(([label,value,boosted])=>`<div class="${boosted?'boosted':''}" data-stat="${label}"><span>${label}</span><b>${value}</b></div>`).join('');
